CREATE TABLE public.profiles (id UUID NOT NULL PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, email TEXT, display_name TEXT, avatar_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own profile" ON public.profiles FOR SELECT TO authenticated USING ((SELECT auth.uid()) = id);
CREATE POLICY "update own profile" ON public.profiles FOR UPDATE TO authenticated USING ((SELECT auth.uid()) = id) WITH CHECK ((SELECT auth.uid()) = id);
CREATE TABLE public.user_roles (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'listener' CHECK (role IN ('listener','artist','admin')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id));
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_user_roles_user_id ON public.user_roles(user_id);
CREATE POLICY "read own role" ON public.user_roles FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE OR REPLACE FUNCTION public.has_role(_role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = (SELECT auth.uid()) AND role = _role); $$;
GRANT EXECUTE ON FUNCTION public.has_role(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles (id, email, display_name) VALUES (NEW.id, NEW.email, COALESCE(NEW.raw_user_meta_data->>'display_name', split_part(NEW.email,'@',1))); INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, 'listener'); RETURN NEW; END; $$;
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();
CREATE TABLE public.artists (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, owner_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, bio TEXT, avatar_key TEXT, banner_key TEXT, monthly_listeners INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.artists ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_artists_owner_id ON public.artists(owner_id);
CREATE POLICY "artists public read" ON public.artists FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "create own artist" ON public.artists FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = owner_id);
CREATE POLICY "update own artist" ON public.artists FOR UPDATE TO authenticated USING ((SELECT auth.uid()) = owner_id) WITH CHECK ((SELECT auth.uid()) = owner_id);
CREATE POLICY "delete own artist" ON public.artists FOR DELETE TO authenticated USING ((SELECT auth.uid()) = owner_id);
CREATE OR REPLACE FUNCTION public.is_artist_owner(_artist_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.artists WHERE id = _artist_id AND owner_id = (SELECT auth.uid())); $$;
GRANT EXECUTE ON FUNCTION public.is_artist_owner(uuid) TO authenticated;
CREATE TABLE public.albums (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, artist_id UUID NOT NULL REFERENCES public.artists(id) ON DELETE CASCADE, title TEXT NOT NULL, cover_key TEXT, release_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.albums ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_albums_artist_id ON public.albums(artist_id);
CREATE POLICY "albums public read" ON public.albums FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "owner insert album" ON public.albums FOR INSERT TO authenticated WITH CHECK (public.is_artist_owner(artist_id));
CREATE POLICY "owner update album" ON public.albums FOR UPDATE TO authenticated USING (public.is_artist_owner(artist_id)) WITH CHECK (public.is_artist_owner(artist_id));
CREATE POLICY "owner delete album" ON public.albums FOR DELETE TO authenticated USING (public.is_artist_owner(artist_id));
CREATE TABLE public.tracks (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, artist_id UUID NOT NULL REFERENCES public.artists(id) ON DELETE CASCADE, album_id UUID REFERENCES public.albums(id) ON DELETE SET NULL, title TEXT NOT NULL, audio_url TEXT NOT NULL, cover_key TEXT, duration_seconds INTEGER NOT NULL DEFAULT 0, genre TEXT, plays INTEGER NOT NULL DEFAULT 0, is_published BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.tracks ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_tracks_artist_id ON public.tracks(artist_id);
CREATE INDEX idx_tracks_album_id ON public.tracks(album_id);
CREATE POLICY "published tracks public read" ON public.tracks FOR SELECT TO anon, authenticated USING (is_published = true);
CREATE POLICY "owner reads own tracks" ON public.tracks FOR SELECT TO authenticated USING (public.is_artist_owner(artist_id));
CREATE POLICY "owner insert track" ON public.tracks FOR INSERT TO authenticated WITH CHECK (public.is_artist_owner(artist_id));
CREATE POLICY "owner update track" ON public.tracks FOR UPDATE TO authenticated USING (public.is_artist_owner(artist_id)) WITH CHECK (public.is_artist_owner(artist_id));
CREATE POLICY "owner delete track" ON public.tracks FOR DELETE TO authenticated USING (public.is_artist_owner(artist_id));
CREATE TABLE public.lyric_lines (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, track_id UUID NOT NULL REFERENCES public.tracks(id) ON DELETE CASCADE, time_ms INTEGER NOT NULL, text TEXT NOT NULL);
ALTER TABLE public.lyric_lines ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_lyric_lines_track_id ON public.lyric_lines(track_id, time_ms);
CREATE POLICY "lyrics public read" ON public.lyric_lines FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY "owner insert lyrics" ON public.lyric_lines FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = track_id AND public.is_artist_owner(t.artist_id)));
CREATE POLICY "owner delete lyrics" ON public.lyric_lines FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.tracks t WHERE t.id = track_id AND public.is_artist_owner(t.artist_id)));
CREATE TABLE public.playlists (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, title TEXT NOT NULL, description TEXT, cover_key TEXT, is_public BOOLEAN NOT NULL DEFAULT false, is_featured BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.playlists ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_playlists_user_id ON public.playlists(user_id);
CREATE POLICY "read public or own playlists" ON public.playlists FOR SELECT TO anon, authenticated USING (is_public = true OR user_id = (SELECT auth.uid()));
CREATE POLICY "insert own playlist" ON public.playlists FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "update own playlist" ON public.playlists FOR UPDATE TO authenticated USING ((SELECT auth.uid()) = user_id) WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "delete own playlist" ON public.playlists FOR DELETE TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE OR REPLACE FUNCTION public.can_read_playlist(_playlist_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.playlists WHERE id = _playlist_id AND (is_public = true OR user_id = (SELECT auth.uid()))); $$;
GRANT EXECUTE ON FUNCTION public.can_read_playlist(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.owns_playlist(_playlist_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.playlists WHERE id = _playlist_id AND user_id = (SELECT auth.uid())); $$;
GRANT EXECUTE ON FUNCTION public.owns_playlist(uuid) TO authenticated;
CREATE TABLE public.playlist_tracks (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, playlist_id UUID NOT NULL REFERENCES public.playlists(id) ON DELETE CASCADE, track_id UUID NOT NULL REFERENCES public.tracks(id) ON DELETE CASCADE, position INTEGER NOT NULL DEFAULT 0, added_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(playlist_id, track_id));
ALTER TABLE public.playlist_tracks ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_playlist_tracks_playlist_id ON public.playlist_tracks(playlist_id, position);
CREATE INDEX idx_playlist_tracks_track_id ON public.playlist_tracks(track_id);
CREATE POLICY "read public playlist tracks" ON public.playlist_tracks FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.playlists p WHERE p.id = playlist_id AND p.is_public = true));
CREATE POLICY "read own playlist tracks" ON public.playlist_tracks FOR SELECT TO authenticated USING (public.owns_playlist(playlist_id));
CREATE POLICY "insert into own playlist" ON public.playlist_tracks FOR INSERT TO authenticated WITH CHECK (public.owns_playlist(playlist_id));
CREATE POLICY "update own playlist tracks" ON public.playlist_tracks FOR UPDATE TO authenticated USING (public.owns_playlist(playlist_id)) WITH CHECK (public.owns_playlist(playlist_id));
CREATE POLICY "delete own playlist tracks" ON public.playlist_tracks FOR DELETE TO authenticated USING (public.owns_playlist(playlist_id));
CREATE TABLE public.liked_tracks (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, track_id UUID NOT NULL REFERENCES public.tracks(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, track_id));
ALTER TABLE public.liked_tracks ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_liked_tracks_user_id ON public.liked_tracks(user_id);
CREATE POLICY "read own likes" ON public.liked_tracks FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE POLICY "insert own like" ON public.liked_tracks FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "delete own like" ON public.liked_tracks FOR DELETE TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE TABLE public.play_history (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, track_id UUID NOT NULL REFERENCES public.tracks(id) ON DELETE CASCADE, played_at TIMESTAMPTZ NOT NULL DEFAULT now());
ALTER TABLE public.play_history ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_play_history_user_id ON public.play_history(user_id, played_at DESC);
CREATE POLICY "read own history" ON public.play_history FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE POLICY "insert own history" ON public.play_history FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "delete own history" ON public.play_history FOR DELETE TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE TABLE public.follows (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, artist_id UUID NOT NULL REFERENCES public.artists(id) ON DELETE CASCADE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(user_id, artist_id));
ALTER TABLE public.follows ENABLE ROW LEVEL SECURITY;
CREATE INDEX idx_follows_user_id ON public.follows(user_id);
CREATE INDEX idx_follows_artist_id ON public.follows(artist_id);
CREATE POLICY "read own follows" ON public.follows FOR SELECT TO authenticated USING ((SELECT auth.uid()) = user_id);
CREATE POLICY "insert own follow" ON public.follows FOR INSERT TO authenticated WITH CHECK ((SELECT auth.uid()) = user_id);
CREATE POLICY "delete own follow" ON public.follows FOR DELETE TO authenticated USING ((SELECT auth.uid()) = user_id);